## `processPayload`

```typescript
/**
 * Validate and transform an API payload.
 *
 * This function receives data of an unknown type. It checks that the data
 * is an object with a `userId` (number) and an `action` (string). If the
 * data is not correct, the function throws an Error with a clear message.
 * If the data is correct, the function returns a new object with a
 * timestamp and a sanitized payload.
 *
 * @param data - The raw API payload of an unknown type.
 * @returns A clean payload object with `userId`, `action`, and `timestamp`.
 *
 * @throws {Error} When the data is not an object.
 * @throws {Error} When the data is null.
 * @throws {Error} When `userId` is missing or not a number.
 * @throws {Error} When `action` is missing or not a string.
 * @throws {Error} When `action` is an empty string.
 *
 * @example
 * ```typescript
 * const result = processPayload({ userId: 42, action: "deploy" });
 * // result = { userId: 42, action: "deploy", timestamp: "2026-07-30T..." }
 * ```
 *
 * @example
 * ```typescript
 * // This call throws an Error.
 * processPayload("not an object");
 * ```
 */
function processPayload(data: unknown): { userId: number; action: string; timestamp: string } {
  // Check that the data is a non-null object.
  if (typeof data !== "object" || data === null) {
    throw new Error("The payload must be a non-null object.");
  }

  // Get the shape of the object.
  const record = data as Record<string, unknown>;

  // Check that userId is a number.
  if (typeof record.userId !== "number") {
    throw new Error("The 'userId' property is missing or is not a number.");
  }

  // Check that action is a non-empty string.
  if (typeof record.action !== "string" || record.action.length === 0) {
    throw new Error("The 'action' property is missing, is not a string, or is empty.");
  }

  // Build and return the clean payload.
  return {
    userId: record.userId,
    action: record.action,
    timestamp: new Date().toISOString(),
  };
}
```

