/**
 * Read user data from the API for a given user ID.
 *
 * This function sends an HTTP GET request to the user endpoint.
 * It reads the response body and returns the user data as an object.
 *
 * @param {string} userId - The unique identifier for the user.
 * @returns {Promise<Object>} The user data object that the API returns.
 *
 * @throws {TypeError} If userId is not a string or is empty.
 * @throws {Error} If the network connection fails.
 * @throws {Error} If the server returns an HTTP status code 4xx or 5xx.
 * @throws {SyntaxError} If the response body is not valid JSON.
 * @throws {Error} If the request does not complete in the time limit.
 */
async function fetchUserData(userId) {
    const TIME_LIMIT_MS = 5000;
    const API_BASE_URL = 'https://api.example.com';

    // Check the input parameter
    if (typeof userId !== 'string' || userId.trim() === '') {
        throw new TypeError('The userId must be a non-empty string.');
    }

    const url = `${API_BASE_URL}/users/${encodeURIComponent(userId)}`;

    // Set a time limit for the request
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), TIME_LIMIT_MS);

    try {
        const response = await fetch(url, { signal: controller.signal });

        if (!response.ok) {
            throw new Error(
                `The server returned status ${response.status} for user ${userId}.`
            );
        }

        return await response.json();

    } catch (error) {
        if (error.name === 'AbortError') {
            throw new Error(
                `The request for user ${userId} did not complete in the time limit.`
            );
        }
        throw error;

    } finally {
        clearTimeout(timer);
    }
}
```
